item.command:
/usr/bin/zsh -lc "cat > candidate.sv <<'EOF'
module TopModule (
    input  logic clk,
    input  logic d,
    output logic q
);
    always_ff @(posedge clk) begin
        q <= d;
    end
endmodule
EOF
cp candidate.sv candidate_initial.sv
cat > dev_tb.sv <<'EOF'
"'`timescale 1ns/1ps
module dev_tb;
    logic clk = 0;
    logic d = 0;
    wire q;
    TopModule dut (.clk(clk), .d(d), .q(q));
    task automatic cycle(input logic value);
        d = value;
        #2;
        clk = 1;
        #1;
        if (q !== value) $fatal(1, "Rising edge capture failed");
        d = ~value;
        #1;
        if (q !== value) $fatal(1, "Output changed between edges");
        clk = 0;
        #1;
        if (q !== value) $fatal(1, "Output changed at falling edge");
        #1;
    endtask
    initial begin
        cycle(0);
        cycle(1);
        cycle(1);
        cycle(0);
        cycle(0);
        cycle(1);
        $display("PASS: rising-edge capture and output hold");
        $finish;
    end
    initial begin
        #100;
        $fatal(1, "Test timeout");
    end
endmodule
EOF
 timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > dev_compile.log 2>&1
compile_status=$?
if [ "$compile_status" -eq 0 ]; then
    timeout 20s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > dev_simulation.log 2>&1
    simulation_status=$?
else
    simulation_status=skipped
fi
printf '"'compile_exit=%s\\nsimulation_exit=%s\\n' \""'$compile_status" "$simulation_status" > dev_status.log
cat dev_status.log dev_compile.log dev_simulation.log'

